<template><ElConfigProvider namespace="kel"><KsDialog :modelValue="true" :teleported="false" :appendToBody="false" :title="title" width="1000px" @update:modelValue="v=>{if(!v&&!locked)emit('close')}"><section class="native-run"><div class="steps"><span v-for="(label,index) in ['选择目标','脚本与通道','预检与确认']" :key="label" :class="{active:step===index,done:step>index}"><i>{{step>index?'✓':index+1}}</i>{{label}}</span></div><div v-if="error" class="error" role="alert">{{error}}</div><fieldset :disabled="locked"><div v-if="step===0"><div class="filters"><KsInput v-model="query" placeholder="搜索 CMDB 名称、资产 ID"/><select v-model="type"><option value="">所有设备</option><option value="server">Server</option><option value="switch">Switch</option></select><KsButton size="small" @click="emit('select',[...new Set([...selected,...visible.filter(t=>!maintained(t)).map(t=>t.id)])])">选择筛选结果</KsButton></div><div class="targets"><label v-for="target in visible" :key="target.id"><input type="checkbox" :checked="selected.includes(target.id)" :disabled="maintained(target)" @change="emit('select',($event.target as HTMLInputElement).checked?[...selected,target.id]:selected.filter(id=>id!==target.id))"/><span><b>{{target.name}}</b><small>{{target.id}} · {{target.type}} · Revision {{target.revision}}</small></span><code>{{maintained(target)?'MAINTAINED · IPMI-only':target.agent_online?'Agent Online':target.ssh_profile_id?'SSH Trusted':'No Transport'}}</code></label><p v-if="!loading&&!visible.length">没有符合条件的 CMDB 设备</p><p v-if="loading">正在加载授权资产…</p></div></div>
<div v-else-if="step===1" class="config"><div class="config-row"><label>执行通道<select :value="request.transport_policy" @change="patch({transport_policy:value($event)})"><option value="agent_preferred">Agent Preferred</option><option value="agent_only">Agent Only</option><option value="ssh_only">SSH Only</option></select></label><label>超时（秒）<input type="number" min="1" max="3600" :disabled="hasFlow" :value="request.timeout_seconds" @change="patch({timeout_seconds:Number(value($event))})"/></label><label>目标并发<input type="number" min="1" max="64" :disabled="hasFlow" :value="request.target_concurrency" @change="patch({target_concurrency:Number(value($event))})"/></label></div><template v-if="!request.steps?.length"><label>脚本类型<select :value="request.kind" @change="patch({kind:value($event)})"><option value="bash">Shell Script</option><option value="python">Python Script</option><option value="command">Command</option><option v-if="!['bash','python','command'].includes(request.kind)" :value="request.kind">{{request.kind}}</option></select></label><NativeCodeEditor :source="request.command" :readOnly="locked" path="quick-run.sh" :language="request.kind==='python'?'python':'shell'" :theme="theme" @change="v=>patch({command:v})" @save="()=>{}"/></template><div v-for="(item,index) in request.steps||[]" :key="index" class="step-config"><div class="config-row"><label>Step ID<input :value="item.id" @change="patchStep(index,{id:value($event)})"/></label><label>类型<select :value="item.kind" @change="patchStep(index,{kind:value($event)})"><option>bash</option><option>python</option><option>command</option></select></label><label>前置步骤<input :value="item.depends_on.join(',')" @change="patchStep(index,{depends_on:value($event).split(',').map(v=>v.trim()).filter(Boolean)})"/></label><KsButton size="small" @click="patch({steps:request.steps.filter((_,i)=>i!==index)})">移除</KsButton></div><NativeCodeEditor :source="item.command" :readOnly="locked" :path="item.id+(item.kind==='python'?'.py':'.sh')" :language="item.kind==='python'?'python':'shell'" :theme="theme" @change="v=>patchStep(index,{command:v})" @save="()=>{}"/><label>输出绑定（ENV=step_id）<input :value="Object.entries(item.inputs||{}).map(([k,v])=>k+'='+v).join(',')" @change="patchStep(index,{inputs:Object.fromEntries(value($event).split(',').filter(s=>s.includes('=')).map(s=>s.split('=',2).map(v=>v.trim())))})"/></label></div><KsButton size="small" :disabled="!request.steps?.length&&!['bash','python','command'].includes(request.kind)" @click="addStep">添加设备步骤</KsButton><p v-if="validationError" class="error" role="alert">{{validationError}}</p><p class="note">状态未知时不会切换通道重复执行。高危操作仍需独立审批；此编辑器不会向设备执行命令。</p></div>
<div v-else class="review"><div class="scope"><b>{{project}}</b><span>{{selected.length}} 台目标 · {{revision?('Flow Revision '+revision):'System Quick Run'}}</span><code>{{request.transport_policy}}</code><KsButton :loading="preflightBusy" :disabled="busy" @click="emit('preflight')">{{decisions?'重新预检':'执行预检'}}</KsButton></div><div v-for="decision in decisions||[]" :key="decision.asset_id" class="decision"><span>{{decision.name||decision.asset_id}}</span><code>{{decision.transport||'未确定'}}</code><span>{{decision.reason||'—'}}</span><b :class="decision.ready?'ready':'blocked'">{{decision.ready?'READY':'BLOCKED'}}</b></div><p v-if="!decisions" class="note">先完成预检；缺失证据、维护态、设备版本变化和审批缺口由后端阻断。</p><details><summary>高危操作审批</summary><div class="config-row"><label>审批域<select :value="request.approval_action||''" @change="patch({approval_action:value($event)})"><option value="">普通作业</option><option v-for="action in ['bios','firmware','bmc_power','reinstall','cleanup']" :key="action">{{action}}</option></select></label><label>理由<input :value="approvalReason" @input="emit('reason',value($event))"/></label><KsButton :loading="approvalBusy" :disabled="!request.approval_action||!approvalReason" @click="emit('approval')">提交审批申请</KsButton></div><label>已批准记录 ID<input :value="request.approval_id||''" @change="emit('approvalId',value($event))"/></label><p class="note">申请人与审批人分离。脚本、范围或目标版本变更后，旧审批不再适用。</p></details><details><summary>本次脚本快照</summary><pre>{{request.steps?.length?request.steps.map(s=>s.id+'\n'+s.command).join('\n\n'):request.command}}</pre></details><div v-if="canSave&&!hasFlow" class="save-draft"><KsInput :modelValue="flowName" placeholder="可复用 Flow 名称" @update:modelValue="v=>emit('flowName',v)"/><KsButton :loading="saveBusy" :disabled="!flowName.trim()" @click="emit('saveFlow')">保存为 Flow 草稿</KsButton></div></div>
</fieldset><footer><span>{{selected.length}} selected · REAL API</span><KsButton :disabled="locked" @click="step?step--:emit('close')">{{step?'上一步':'取消'}}</KsButton><KsButton v-if="step<2" type="primary" :disabled="locked||(step===0?(!selected.length||selected.length>200):!!validationError)" @click="step++">下一步</KsButton><KsButton v-else type="primary" :loading="busy" :disabled="locked||!!validationError||!!request.approval_action&&!request.approval_id||!allowed||!decisions?.length||decisions.some(d=>!d.ready)||decisions.length!==selected.length" @click="emit('execute')">创建执行</KsButton></footer></section></KsDialog></ElConfigProvider></template>
<script setup lang="ts">
import {computed,ref} from 'vue';import {runDraftError} from '../flows/definition';import {ElConfigProvider} from 'element-plus';import KsDialog from '../../vendor/kestra/design-system/components/Feedback/KsDialog.vue';import KsButton from '../../vendor/kestra/design-system/components/Basic/KsButton/KsButton.vue';import KsInput from '../../vendor/kestra/design-system/components/Form/KsInput.vue';import NativeCodeEditor from './NativeCodeEditor.vue';
const props=defineProps<{title:string;project:string;request:any;targets:any[];selected:string[];decisions:any[]|null;allowed:boolean;canSave:boolean;hasFlow:boolean;revision:number;loading:boolean;busy:boolean;preflightBusy:boolean;saveBusy:boolean;approvalBusy:boolean;approvalReason:string;flowName:string;error:string;theme:'dark'|'light'}>(),emit=defineEmits(['close','patch','select','preflight','execute','reason','approval','approvalId','flowName','saveFlow']);const step=ref(0),query=ref(''),type=ref('');
const value=(e:Event)=>(e.target as HTMLInputElement).value,maintained=(t:any)=>Object.values(t.fields||{}).includes('maintained');
const visible=computed(()=>props.targets.filter(t=>(!type.value||t.type===type.value)&&[t.id,t.name].join(' ').toLowerCase().includes(query.value.toLowerCase()))),validationError=computed(()=>runDraftError(props.request)),locked=computed(()=>props.busy||props.preflightBusy||props.approvalBusy);
const newStepID=()=>'step_'+crypto.randomUUID().slice(0,6);
function addStep(){const steps=[...(props.request.steps||[])];if(!steps.length&&props.request.command.trim()){if(!['bash','python','command'].includes(props.request.kind))return;steps.push({id:'command',kind:props.request.kind,command:props.request.command,depends_on:[],inputs:{}})}steps.push({id:newStepID(),kind:'bash',command:'',depends_on:steps.length?[steps.at(-1).id]:[],inputs:{}});patch({steps})}
const patch=(p:any)=>emit('patch',p),patchStep=(index:number,p:any)=>patch({steps:props.request.steps.map((s,i)=>i===index?{...s,...p}:s)});
</script>
<style scoped>.native-run{color:var(--ks-text-primary);font:12px var(--ks-font-family-sans)}.steps{display:flex;gap:32px;margin-bottom:24px;border-bottom:1px solid var(--ks-border-default);padding-bottom:18px}.steps>span{display:flex;gap:8px;align-items:center;color:var(--ks-text-secondary)}.steps>span.active{color:var(--ks-text-link)}.steps i{font-style:normal;border:1px solid var(--ks-border-default);border-radius:50%;width:22px;height:22px;display:grid;place-items:center;font-size:10px}.steps .done i{color:#43b89b}.filters,.config-row,.scope,.save-draft{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.filters{margin-bottom:12px}.filters>.kel-input{max-width:380px}.targets{max-height:400px;overflow:auto}.targets>label{display:flex;align-items:center;gap:12px;padding:14px 4px;border-bottom:1px solid var(--ks-border-default)}.targets>label>span{flex:1}.targets small{display:block;font-size:10px;color:var(--ks-text-secondary);margin-top:5px}.targets code{font-size:10px;color:var(--ks-text-secondary)}label{display:block;font-size:11px;color:var(--ks-text-secondary);margin:8px 0}input:not([type=checkbox]),select{display:block;background:var(--ks-bg-input);border:1px solid var(--ks-border-default);border-radius:4px;padding:7px;color:var(--ks-text-primary);font-size:12px;margin-top:5px}.config-row>label{flex:1;min-width:130px}.config-row input,.config-row select{width:100%;box-sizing:border-box}.native-run :deep(.native-code-editor){height:240px;min-height:200px;border:1px solid var(--ks-border-default);border-radius:4px;margin:14px 0}.config{max-height:520px;overflow:auto}.note{font-size:11px;line-height:1.7;color:var(--ks-text-secondary)}.scope{padding:10px 0 18px}.scope>span{color:var(--ks-text-secondary)}.scope>button{margin-left:auto}.decision{display:grid;grid-template-columns:1fr 100px 2fr 80px;gap:12px;padding:12px 0;border-bottom:1px solid var(--ks-border-default);font-size:11px}.ready{color:#43b89b}.blocked,.error{color:#e0758e}.error{padding:10px 0}.review{max-height:520px;overflow:auto}.review details{margin-top:18px}.review summary{cursor:pointer;font-size:11px}.review pre{font:11px/1.6 monospace;max-height:220px;overflow:auto}.save-draft{margin-top:18px}.save-draft>.kel-input{max-width:400px}footer{display:flex;gap:10px;align-items:center;border-top:1px solid var(--ks-border-default);padding-top:18px;margin-top:18px}footer>span{margin-right:auto;font-size:10px;color:var(--ks-text-secondary)}.step-config{border-top:1px solid var(--ks-border-default);padding:10px 0}</style>

<style scoped>.native-run>fieldset{border:0;padding:0;margin:0;min-width:0}.native-run>fieldset:disabled{opacity:.75}</style>
